    h, w = len(grid), len(grid[0])
    bg = max(set(v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid))
    counts = {}
    for row in grid:
        for v in row:
            if v != bg:
                counts[v] = counts.get(v, 0) + 1
    marker = max(counts, key=counts.get)
    pts = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == marker]
    source = [(r, c, grid[r][c]) for r in range(h) for c in range(w)
              if grid[r][c] != bg and grid[r][c] != marker]
    r0 = min(r for r, c, v in source)
    r1 = max(r for r, c, v in source)
    c0 = min(c for r, c, v in source)
    c1 = max(c for r, c, v in source)
    ar, ac = (r0 + r1) // 2, (c0 + c1) // 2
    rel = [(r - ar, c - ac, v) for r, c, v in source]
    out = [row[:] for row in grid]
    for r, c in pts:
        for dr, dc, v in rel:
            rr, cc = r + dr, c + dc
            if 0 <= rr < h and 0 <= cc < w:
                out[rr][cc] = v
    return out

